result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "poker.py", "content": """"5-card poker hand evaluator (stdlib only).

Cards are (rank, suit) tuples: rank 2..14 (Ace=14), suit 0..3.
evaluate() returns a (category, tiebreak) tuple where larger tuples are
better hands, so plain `<`, `==` etc. work correctly.
"""

# Categories (higher beats lower)
STRAIGHT_FLUSH = 9
FOUR_OF_A_KIND = 8
FULL_HOUSE = 7
FLUSH = 6
STRAIGHT = 5
THREE_OF_A_KIND = 4
TWO_PAIR = 3
ONE_PAIR = 2
HIGH_CARD = 1

CATEGORY_NAMES = {
    STRAIGHT_FLUSH: "straight flush",
    FOUR_OF_A_KIND: "four of a kind",
    FULL_HOUSE: "full house",
    FLUSH: "flush",
    STRAIGHT: "straight",
    THREE_OF_A_KIND: "three of a kind",
    TWO_PAIR: "two pair",
    ONE_PAIR: "one pair",
    HIGH_CARD: "high card",
}


def evaluate(hand):
    """Return (category, tiebreak_tuple) for a 5-card hand."""
    counts = [0] * 15
    suit0 = hand[0][1]
    is_flush = True
    for r, s in hand:
        counts[r] += 1
        if s != suit0:
            is_flush = False

    # Group ranks by multiplicity: singles, pairs, trips, quads
    quad = trip = 0
    pairs = []          # high to low
    singles = []        # high to low
    for r in range(14, 1, -1):
        c = counts[r]
        if c == 4:
            quad = r
        elif c == 3:
            trip = r
        elif c == 2:
            pairs.append(r)
        elif c == 1:
            singles.append(r)

    # Straight detection (only possible when all 5 ranks are distinct)
    straight_high = 0
    if not pairs and not quad and not trip:
        if singles[0] - singles[4] == 4:
            straight_high = singles[0]
        elif singles[0] == 14 and singles[1] == 5:  # A-2-3-4-5 wheel
            straight_high = 5

    if straight_high and is_flush:
        return (STRAIGHT_FLUSH, (straight_high,))
    if quad:
        return (FOUR_OF_A_KIND, (quad, singles[0]))
    if trip and pairs:
        return (FULL_HOUSE, (trip, pairs[0]))
    if is_flush:
        return (FLUSH, tuple(singles))
    if straight_high:
        return (STRAIGHT, (straight_high,))
    if trip:
        return (THREE_OF_A_KIND, (trip,) + tuple(singles))
    if len(pairs) == 2:
        return (TWO_PAIR, (pairs[0], pairs[1], singles[0]))
    if pairs:
        return (ONE_PAIR, (pairs[0],) + tuple(singles))
    return (HIGH_CARD, tuple(singles))


DECK = [(r, s) for r in range(2, 15) for s in range(4)]


def all_hands():
    from itertools import combinations
    return combinations(DECK, 5)
